-- 1) generic inbox asset under customer MYIO
INSERT INTO assets (id, tenant_id, customer_id, parent_asset_id, path, depth, name, display_name, code, type, status)
SELECT 'a0000062-0000-4000-8000-000000000001', c.tenant_id, c.id, NULL, 'a0000062-0000-4000-8000-000000000001', 0,
